// SIAARA DICOM Toolkit - named data layer: every PS3.3 module and macro as data.
//
// The tables (src/modules/module_tables.inc) are generated by tools/gen_modules.py from the DICOM
// standard (PS3.3 module / macro attribute tables, PS3.6 keywords, VR and VM). Nothing here
// interprets values: the layer tells which attributes a module has and where a value lives, and
// the path API returns values exactly as stored (text decoded with the Specific Character Set).
#pragma once

#include <cstdint>
#include <optional>
#include <span>
#include <string>
#include <string_view>
#include <vector>

#include "core/dataset.hpp"
#include "core/status.hpp"
#include "core/types.hpp"

namespace siaara::modules {

enum class NodeKind : std::int32_t { Module = 1, Macro = 2, Item = 3, Table = 4, FunctionalGroups = 5 };

// One distinct attribute of the tables. mask is 0xFFFFFFFF except for repeating groups (60xx).
struct ModAttr {
    Tag tag;
    Tag mask;
    std::string_view keyword;  // PS3.6 keyword
    std::string_view vr;       // "US", or "US/SS" when the VR depends on context
    std::string_view vm;       // PS3.6 VM, e.g. "1", "2-n"
    bool retired;
};

// A row of a node: an attribute (attr >= 0, node = item node of a sequence or -1) or an Include
// row (attr = -1, node = the included node). type: 0 = not given (normalized IODs), 1 = 1, 2 = 1C,
// 3 = 2, 4 = 2C, 5 = 3, 6 = Include, 7 = conditional Include ("Include ... if ...").
struct ModEntry {
    std::int32_t attr;
    std::int32_t node;
    std::int32_t type;
};

// A module, macro, other attribute table, the set of all Functional Group Macros, or the item of a
// sequence (rows one '>' deeper) defined inside a table.
struct ModNode {
    std::string_view name;        // e.g. "RT Beams Module", "Code Sequence Macro", "RT Beams Module > BeamSequence item"
    std::string_view table_id;    // e.g. "C.8-50"; empty for item nodes
    std::string_view class_name;  // generated C# class (Siaara.Modules)
    std::int32_t kind;            // NodeKind
    std::uint32_t first;
    std::uint32_t count;
};

// An attribute after Include rows are expanded (recursively; a node already being expanded is
// skipped, so recursive definitions terminate). The first definition of a tag wins.
struct FlatAttr {
    const ModAttr* attr;
    std::int32_t type;       // as ModEntry::type (0..5)
    std::int32_t item_node;  // item node of a sequence, or -1
};

std::span<const ModNode> nodes() noexcept;
std::span<const ModEntry> entries(const ModNode& n) noexcept;
const ModAttr* attribute(std::int32_t index) noexcept;
std::span<const ModAttr> attributes() noexcept;
// Flattened attributes of node `index` (cached; thread safe).
const std::vector<FlatAttr>& flattened(std::uint32_t index);

// Finds a node by name, case-insensitively: "RT Beams", "RT Beams Module", "C.8-50",
// "table_C.8-50", or the C# class name "RTBeamsModule". Item nodes match only their full name.
std::optional<std::uint32_t> find_node(std::string_view name) noexcept;

// True when at least one flattened attribute of the node is present at the top level of ds
// (repeating groups: any group of the range).
bool node_present(const Dataset& ds, std::uint32_t index);

// ---------------------------------------------------------------- path API
// path := segment ('.' segment)*
// segment := name [ '[' index ']' ]
// name := Keyword | (gggg,eeee) | gggg,eeee | creator:gggg,xx | "creator":gggg,xx
// A sequence segment that is not the last needs an item index. On the last segment, an index
// selects an item of a sequence, or a value of a multi-valued element. Private attributes are
// found through their Private Creator block (gggg,00bb) in the data set being walked; an unquoted
// creator cannot contain '.', '[' or ']'. A repeating-group keyword (OverlayRows, CurveDimensions,
// ...) names the first group, 6000 or 5000; other groups are addressed by tag, e.g. (6002,0010).
enum class ValueKind : std::int32_t { Empty = 0, Text = 1, Integer = 2, Real = 3, Binary = 4, Sequence = 5, Tag = 6, Item = 7 };

struct PathTarget {
    const Dataset* parent = nullptr;     // data set holding the element (or the item's sequence)
    const Element* element = nullptr;    // the last segment's element
    const Dataset* item = nullptr;       // last segment is a sequence with an index: the item
    std::int64_t index = -1;             // the last segment's index, -1 when none
    std::string charset;                 // raw (0008,0005) in force for parent ("" = default)
};
Result<PathTarget> resolve_path(const Dataset& root, std::string_view path);

struct PathValue {
    Tag tag = 0;
    VR vr = VR::None;
    std::uint32_t vm = 0;
    ValueKind kind = ValueKind::Empty;
    std::int64_t value_index = -1;
    std::uint32_t item_count = 0;
    std::uint64_t byte_length = 0;
    bool has_integer = false;
    std::int64_t integer = 0;
    bool has_real = false;
    double real = 0;
    std::string text;  // UTF-8; all values backslash separated, or the selected value
    // Byte sequences of the element that are not characters of the character set in force and
    // are U+FFFD in `text` (0: the text is exactly what the bytes hold). The bytes are unchanged.
    std::uint32_t undecodable = 0;
};
Result<PathValue> get_by_path(const Dataset& root, std::string_view path);
// Every value of the element as double (numeric VRs, including OF / OD / OL / OV / OW and the
// numeric strings DS / IS). An index on the last segment selects one value.
// One pass over the element (R-111). LimitExceeded when the result would exceed
// kNamedDataMemoryBudget, OutOfMemory when the allocation fails (never an exception, R-123).
Result<std::vector<double>> doubles_by_path(const Dataset& root, std::string_view path);
// The number of values doubles_by_path would return, from the value count alone: nothing is
// decoded or allocated, so a value that is not a number is reported only by the calls that read it.
Result<std::size_t> doubles_by_path_count(const Dataset& root, std::string_view path);
// The same values written straight into `out`, whose size must be doubles_by_path_count().
Status doubles_by_path_into(const Dataset& root, std::string_view path, std::span<double> out);

// Memory budget of the vectors the named data layer returns (doubles_by_path, waveform_raw,
// waveform_scaled, device_positions): the toolkit's default allocation budget, 4 GiB (as
// codec::FrameInfo::kDefaultMemoryBudget and image::FrameReader). The *_into forms write into the
// caller's buffer and allocate nothing.
inline constexpr std::uint64_t kNamedDataMemoryBudget = std::uint64_t{4} << 30;
constexpr bool fits_named_data_budget(std::uint64_t count, std::uint64_t element_size) noexcept {
    return element_size == 0 || count <= kNamedDataMemoryBudget / element_size;
}

}  // namespace siaara::modules
